'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { api } from '@/lib/api';

interface User {
    uid: string;
    email: string;
    name: string;
    role: string;
    tenant_id: string | null;
    user_id: string;
    department_id?: string | null;
    tenant_name?: string | null;
    subscription_plan?: string | null;
    trial_ends_at?: string | null;
}

interface AuthContextType {
    user: User | null;
    loading: boolean;
    isAuthenticated: boolean;
    loginWithToken: (token: string, userData: any) => void;
    logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<User | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Restore session from localStorage
        const storedToken = localStorage.getItem('auth_token');
        const storedUser = localStorage.getItem('auth_user');

        if (storedToken && storedUser) {
            try {
                const parsedUser = JSON.parse(storedUser);
                api.setToken(storedToken);
                setUser(parsedUser);

                // Verify session is still valid by calling /me
                api.get('/api/auth/me').then((res: any) => {
                    if (res.success) {
                        setUser(res.data);
                        localStorage.setItem('auth_user', JSON.stringify(res.data));
                    } else {
                        // Token invalid, clear session
                        logout();
                    }
                }).catch(() => {
                    // Backend not available, keep local session
                });
            } catch {
                logout();
            }
        }
        setLoading(false);
    }, []);

    const loginWithToken = (token: string, userData: any) => {
        api.setToken(token);
        setUser(userData);
        localStorage.setItem('auth_token', token);
        localStorage.setItem('auth_user', JSON.stringify(userData));
    };

    const logout = () => {
        api.setToken('');
        setUser(null);
        localStorage.removeItem('auth_token');
        localStorage.removeItem('auth_user');
    };

    return (
        <AuthContext.Provider value={{
            user,
            loading,
            isAuthenticated: !!user,
            loginWithToken,
            logout,
        }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}
